const residents={rhea:{name:'RHEA VALE',role:'SCOUT · LEVEL 04',quote:'“The old world left us the tools. We decide what to build.”',portrait:'portrait-rhea',needs:[82,64,91]},jonah:{name:'JONAH REYES',role:'GARDENER · LEVEL 03',quote:'“Give me a patch of dirt and a little patience.”',portrait:'portrait-rhea',needs:[71,78,86]},lio:{name:'LIO PARK',role:'RADIO TECH · LEVEL 02',quote:'“Every signal is a promise that someone is still out there.”',portrait:'portrait-rhea',needs:[93,45,68]}};
let selected='rhea', paused=false, hour=9, minute=42, resources={water:24,food:38,scrap:126};
const $=s=>document.querySelector(s);
function toast(msg){const t=$('#toast');t.textContent=msg;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2500)}
function updateResident(id){selected=id;const r=residents[id];$('#residentName').textContent=r.name;$('#residentRole').textContent=r.role;$('#quote').textContent=r.quote;['energy','hunger','spirit'].forEach((n,i)=>{$('#'+n+'Bar').style.width=r.needs[i]+'%';$('#'+n+'Value').textContent=r.needs[i]});document.querySelectorAll('.character').forEach(el=>el.classList.toggle('selected',el.dataset.person===id));toast(r.name+' selected')}
function changeNeeds(delta){const r=residents[selected];r.needs=r.needs.map((n,i)=>Math.max(0,Math.min(100,n+(Array.isArray(delta)?delta[i]:delta))));updateResident(selected)}
function setResources(){Object.entries(resources).forEach(([k,v])=>$('#'+k+'Count').textContent=v)}
function action(type){document.querySelectorAll('.action').forEach(x=>x.classList.toggle('selected',x.dataset.action===type));const messages={scavenge:'Rhea found a sealed toolbox in the collapsed bus.',craft:'The workbench is humming. Something useful is taking shape.',social:'The fire crackles. Spirits rise around the circle.',rest:'A quiet hour passes beneath the shade.'};$('#actionStatus').textContent=messages[type];if(type==='scavenge'){resources.scrap+=12;changeNeeds([-8,-3,3]);toast('+12 salvaged parts · new find logged')}if(type==='craft'){resources.scrap=Math.max(0,resources.scrap-10);resources.water+=1;toast('Purifier cartridge crafted · +1 water')}if(type==='social'){changeNeeds([2,0,9]);toast('The settlement mood is brighter')}if(type==='rest'){changeNeeds([15,-5,2]);toast('Energy restored · day moves on')}setResources()}
function openEvent(){ $('#modal').classList.add('open') }
function closeEvent(){ $('#modal').classList.remove('open') }
function advanceTime(){if(paused)return;minute+=1;if(minute>59){minute=0;hour++;if(hour>23)hour=0}$('#timeText').textContent=String(hour).padStart(2,'0')+':'+String(minute).padStart(2,'0');$('#timeIcon').textContent=hour>=18||hour<6?'☾':'☀'}
document.querySelectorAll('.character').forEach(el=>el.addEventListener('click',()=>updateResident(el.dataset.person)));
document.querySelectorAll('.action').forEach(el=>el.addEventListener('click',()=>action(el.dataset.action)));
$('#pauseBtn').addEventListener('click',()=>{paused=!paused;$('#pauseBtn').textContent=paused?'▶':'Ⅱ';toast(paused?'World paused':'World resumed')});$('#eventBtn').addEventListener('click',openEvent);$('#modalClose').addEventListener('click',closeEvent);$('#declineBtn').addEventListener('click',()=>{closeEvent();toast('The traveler continues down the south road.')});$('#acceptBtn').addEventListener('click',()=>{closeEvent();resources.food+=6;resources.water-=2;$('#moodText').textContent='WELCOMING';$('#moodMeter').style.width='88%';setResources();toast('Shelter offered · supplies exchanged')});$('#buildBtn').addEventListener('click',()=>{document.body.classList.toggle('build-mode');toast(document.body.classList.contains('build-mode')?'Build mode: choose a site':'Build mode closed')});$('#mapBtn').addEventListener('click',()=>toast('Map unlocked: 3 nearby points of interest'));$('#soundBtn').addEventListener('click',e=>{e.currentTarget.textContent=e.currentTarget.textContent==='◒'?'◑':'◒';toast('Ambient radio toggled')});$('#helpBtn').addEventListener('click',()=>{openEvent();$('#modalTitle').textContent='How to play';$('#modalBody').textContent='Select a resident in the world, then choose an action from the bottom bar. Scavenge resources, craft supplies, gather for spirit, and rest to recover energy. Events shape the settlement.';$('#acceptBtn').textContent='GOT IT';$('#declineBtn').style.display='none'});$('#inspectBtn').addEventListener('click',()=>toast(residents[selected].name+' is ready for an assignment'));
setInterval(advanceTime,3000);setResources();

