document.querySelectorAll('.action').forEach(el=>el.addEventListener('click',()=>action(el.dataset.action)));
$('#pauseBtn').addEventListener('click',()=>{paused=!paused;$('#pauseBtn').textContent=paused?'▶':'Ⅱ';toast(paused?'World paused':'World resumed')});$('#eventBtn').addEventListener('click',openEvent);$('#modalClose').addEventListener('click',()=>{closeEvent();resetModal()});$('#declineBtn').addEventListener('click',()=>{closeEvent();toast('The traveler continues down the south road.')});$('#acceptBtn').addEventListener('click',()=>{if(helpMode){closeEvent();resetModal();return}closeEvent();resources.food+=6;resources.water-=2;$('#moodText').textContent='WELCOMING';$('#moodMeter').style.width='88%';setResources();toast('Shelter offered · supplies exchanged')});$('#buildBtn').addEventListener('click',()=>{document.body.classList.toggle('build-mode');toast(document.body.classList.contains('build-mode')?'Build mode: choose a site':'Build mode closed')});$('#mapBtn').addEventListener('click',()=>toast('Map unlocked: 3 nearby points of interest'));$('#soundBtn').addEventListener('click',e=>{e.currentTarget.textContent=e.currentTarget.textContent==='◒'?'◑':'◒';toast('Ambient radio toggled')});$('#helpBtn').addEventListener('click',()=>{helpMode=true;$('#modalTitle').textContent='How to play';$('#modalBody').textContent='Select a resident in the world, then choose an action from the bottom bar. Scavenge resources, craft supplies, gather for spirit, and rest to recover energy. Click settlement objectives to spend salvage on upgrades. Events shape the settlement.';$('#acceptBtn').textContent='GOT IT';$('#declineBtn').style.display='none';openEvent()});$('#inspectBtn').addEventListener('click',()=>toast(residents[selected].name+' is ready for an assignment'));
const objectiveTasks={water:{cost:20,label:'Purifier upgraded',counter:'3 / 3'},garden:{cost:8,label:'Seeds planted in the community garden',counter:'1 / 1'},radio:{cost:15,label:'Long-range radio repaired',counter:'1 / 1'}};
document.querySelectorAll('.objective').forEach(button=>button.addEventListener('click',()=>{const task=objectiveTasks[button.dataset.objective];if(button.classList.contains('complete')){toast(task.label+' · already done');return}if(resources.scrap<task.cost){toast('Not enough salvaged parts · scavenge first');return}resources.scrap-=task.cost;setResources();button.classList.add('complete');button.querySelector('.check').classList.remove('empty');button.querySelector('.check').textContent='✓';button.querySelector('em').textContent=task.counter;button.querySelector('small').textContent=task.label;toast(task.label+' · −'+task.cost+' parts')}));
$('#scene').addEventListener('click',e=>{if(!document.body.classList.contains('build-mode')||e.target.closest('.character'))return;document.body.classList.remove('build-mode');if(resources.scrap<25){toast('Build needs 25 salvaged parts');return}resources.scrap-=25;setResources();toast('A new shelter foundation is marked for construction')});
setInterval(advanceTime,3000);setResources();
